import {poweredDevice,pinVoltage,logic} from './bus-electrical.js';
export const HALF_STEPS=[8,12,4,6,2,3,1,9];
// Explicit affine L298 approximation: total leg drop matches typical 1A table.
export function stampActuator(c,{net,branch,sensors,addNode}){
 if(c.type==='stepper28byj'){for(let i=1;i<=4;i++){const out=addNode('$coil:'+c.id+':'+i);branch(c.id+':coil'+i,net(c,'VCC'),out,c.params.coilOhms??50);branch(c.id+':input'+i,net(c,'IN'+i),net(c,'GND'),2700);sensors.push({id:c.id+':sink'+i,vcc:net(c,'VCC'),gnd:net(c,'GND'),out,min:4.5,max:5.5,ohms:1,compute:(s,v,g)=>{const input=s.voltages.get(net(c,'IN'+i));return Number.isFinite(input)&&input-g>=2.5?g+.9:null;}});}return true;}
 if(c.type==='l298n'){branch(c.id+':logic-load',net(c,'VSS'),net(c,'GND'),1000);for(const pin of['ENA','ENB','IN1','IN2','IN3','IN4'])branch(c.id+':input:'+pin,net(c,pin),net(c,'GND'),50000);for(let i=1;i<=4;i++){const out=addNode(net(c,'OUT'+i)),pair=i<=2?'A':'B';sensors.push({id:c.id+':OUT'+i,vcc:net(c,'VS'),gnd:net(c,'GND'),out,min:4.8,max:46,ohms:.45,compute:(s,v,g)=>{const supply=s.voltages.get(net(c,'VSS')),enable=s.voltages.get(net(c,'EN'+pair)),input=s.voltages.get(net(c,'IN'+i));if(!Number.isFinite(supply)||supply-g<4.5||supply-g>7||!Number.isFinite(enable)||enable-g<2.3||!Number.isFinite(input))return null;if(input-g>=2.3)return v-.9;if(input-g<=1.5)return g+.8;return null;}});}return true;}
 return false;
}
export function attachActuatorRuntime(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,refreshing=false,key='';
 const commit=()=>{const drivers=[...states.values()].filter(d=>d.type==='ws2812'&&d.powered).flatMap(d=>[{endpoint:d.id+':DOUT',voltage:d.forward?d.voltage:0,ohms:50},{endpoint:d.id+':VCC',voltage:0,ohms:5/(.008+.02*d.frame.flat().reduce((a,b)=>a+b,0)/255)}]),next=JSON.stringify(drivers);if(key!==next){key=next;engine.setDrivers('actuators',drivers);}};
 const refresh=()=>{if(disposed||refreshing)return;refreshing=true;try{const dc=engine.solution,cycle=runtime.cpu.cycles;for(const d of states.values()){const c=project.components.find(c=>c.id===d.id),power=poweredDevice(dc,d.id,{min:4.5,max:d.type==='ws2812'?5.3:5.5});if(d.powered&&!power.powered){d.epoch++;d.bits=[];d.frame=Array.from({length:8},()=>[0,0,0]);d.forward=false;d.lastIndex=null;d.level=false;}Object.assign(d,power);if(!d.powered)continue;
  if(d.type==='stepper28byj'){const currents=Array.from({length:4},(_,i)=>dc.currents.get(d.id+':coil'+(i+1))??0),mask=currents.reduce((m,a,i)=>a>.01?m|(1<<(3-i)):m,0),index=HALF_STEPS.indexOf(mask);d.currents=currents;d.mask=mask;if(index>=0&&index!==d.lastIndex){if(d.lastIndex!==null){let delta=(index-d.lastIndex+8)%8;if(delta>4)delta-=8;if(Math.abs(delta)<=2)d.steps+=delta;else d.invalid++;}d.lastIndex=index;}else if(index<0&&mask!==d.previousMask)d.invalid++;d.previousMask=mask;d.angle=d.steps/(64*(c.params.gearRatio??64))*360;
  }else{const high=logic(pinVoltage(dc,d.id,'DIN'),d.voltage);if(high===true&&!d.level){d.highAt=cycle;d.idle++;d.forward=d.bits.length>=192;d.level=true;}if(high===false&&d.level){const width=cycle-d.highAt,zero=width>=3.2&&width<=8,one=width>=12&&width<=16.8;d.bits.push(one?1:0);if(!zero&&!one)d.bad=true;if(d.bits.length>192*16)d.bad=true;d.forward=false;d.level=false;const idle=++d.idle,epoch=d.epoch;runtime.cpu.addClockEvent(()=>{if(disposed||epoch!==d.epoch||idle!==d.idle||d.level||!d.powered)return;if(d.bits.length>=192&&!d.bad){d.frame=Array.from({length:8},(_,i)=>{const bytes=[];for(let b=0;b<3;b++){let value=0;for(let bit=0;bit<8;bit++)value=(value<<1)|d.bits[i*24+b*8+bit];bytes.push(value);}return[bytes[1],bytes[0],bytes[2]];});d.frames++;}else if(d.bits.length)d.errors++;d.bits=[];d.bad=false;commit();},51*16);}}
 }commit();}finally{refreshing=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>['ws2812','stepper28byj'].includes(c.type))){ids.add(c.id);if(!states.has(c.id))states.set(c.id,{id:c.id,type:c.type,epoch:0,idle:0,powered:false,bits:[],frame:Array.from({length:8},()=>[0,0,0]),frames:0,errors:0,steps:0,angle:0,lastIndex:null,invalid:0,mask:0});}for(const[id,d]of states)if(!ids.has(id)){d.epoch++;states.delete(id);}refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);
 return{updateProject(next){project=next;reconcile();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:d.type,powered:d.powered,frame:d.frame,frames:d.frames,errors:d.errors,steps:d.steps,angle:d.angle,mask:d.mask,currents:d.currents,invalid:d.invalid}]))};},dispose(){disposed=true;for(const d of states.values())d.epoch++;unsubscribe();engine.setDrivers('actuators',[]);}};
}
